import{_ as e,o,c as a,a2 as n}from"./chunks/framework.Dnb1kVW5.js";const w=JSON.parse('{"title":"Statement downloader","description":"","frontmatter":{"title":"Statement downloader"},"headers":[],"relativePath":"docs/tools/statement-downloader.md","filePath":"docs/tools/statement-downloader.md","lastUpdated":1789194236000}'),r={name:"docs/tools/statement-downloader.md"};function s(i,t,d,l,h,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="statement-downloader" tabindex="-1">Statement downloader <a class="header-anchor" href="#statement-downloader" aria-label="Permalink to &quot;Statement downloader&quot;">​</a></h1><p>Instead of manually logging into your bank&#39;s website and downloading statements one by one, the Statement Downloader can do it for you, for supported institutions.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>Launch browser</strong> — Orby opens a browser window for you.</li><li><strong>Log in and navigate</strong> — you log in on the real bank site yourself (Orby never sees or stores your credentials) and go to the statements page.</li><li><strong>Scan</strong> — Orby highlights the statement links it recognizes on the page.</li></ol><p>From there, choose the account and year(s) you want, and download. Files are saved to a per-institution folder shown in the tool, which you can change.</p><h2 id="adding-support-for-a-new-institution" tabindex="-1">Adding support for a new institution <a class="header-anchor" href="#adding-support-for-a-new-institution" aria-label="Permalink to &quot;Adding support for a new institution&quot;">​</a></h2><p>Only supported institutions can be scanned. If yours isn&#39;t recognized yet, see the <a href="/orby-releases/docs/tools/statement-downloader-builder">Statement Downloader Builder</a>.</p>',7)])])}const p=e(r,[["render",s]]);export{w as __pageData,p as default};
